def store_files(ds, source_bucket, year, month, day):

    bands_pth = {
    "SVI01" : "VIIRS-I1-SDR",
    "SVI02" : "VIIRS-I2-SDR",
    "SVI04" : "VIIRS-I4-SDR",
    "SVI05" : "VIIRS-I5-SDR",
    "GITCO" : "VIIRS-IMG-GEO-TC"
    }

    for band in bands_pth.keys():
        
        fname = ds.attrs[band] 
        pref = f"{bands_pth[band]}/{year}/{str(month).zfill(2)}/{str(day).zfill(2)}/{fname}"
        sdr_blob = list(source_bucket.list_blobs(prefix=pref))#[0]

        if len(sdr_blob) > 0:
            return sdr_blob
        
        else:
            return None


