class ViirsCloudDataset(BaseDataset):
    "Subclass of `BaseDataset` to process VIIRS bands in accordance with its spatial resolution."
    _name = None 
    def __init__(self, paths:InOutPath, region:Region,
                 times:pd.DatetimeIndex=None, bands:list=None, bucket_name=None):
        self.bucket = bucket_name
        match region.name:
            case 'ambr':
                self.bk_region = 'amazonia'
            case 'cebr':
                self.bk_region = 'cerrado'
            case 'sulbr':
                self.bk_region = 'sul'
        storage_client = storage.Client()
        self.source_bucket = storage_client.bucket(bucket_name)
        self.source_prefix = f"{self.bk_region}/ladsweb/"
        self.destination_prefix = f"{self.bk_region}/dataset/"
        self.blobs = list(self.source_bucket.list_blobs(prefix=self.source_prefix))
        super().__init__(self._name, paths, region, times, bands)
        self.times = self.check_files()

      
    def list_files(self, time:pd.Timestamp)-> list:
        if time in self.times:
            pattern = re.compile(f'_d{str(time.year)}{str(time.month).zfill(2)}{str(time.day).zfill(2)}_*')
            files = [blob for blob in self.blobs if re.search(pattern, blob.name)]
        return files
    
    def list_pattern(self, pattern:str)-> list:
        ''' Padrao de busca SVI{band_nrs[0]}_j01_{date_aq}_{time_aq} ou GITCO'''
        pattern_str = re.compile(f'{pattern}*') 
        files =  [blob for blob in self.blobs if re.search(pattern_str, blob.name)]
        return files

    def check_files(self):
        not_missing = []
        for i, t in tqdm(enumerate(self.times), total=len(self.times)):
            files = self.list_files(t)
            if len(files)==0:
                print(f'Missing files for {t}')
            else: not_missing.append(i)
        return self.times[not_missing]

    def find_dates(self, first:pd.Timestamp=None, last:pd.Timestamp=None):
        pattern = r"d(\d{4})(\d{2})(\d{2})_"
        times = []
        for f in self.blobs:
            x = re.search(pattern, f.name)
            if x is not None:
                year, month, day = map(x.group, [1,2,3])
                times.append(pd.Timestamp(f'{year}-{month}-{day}'))
        self.times = pd.DatetimeIndex(sorted(set(times)))
        if first is not None:
            self.times = self.times[self.times>=first]
        if last is not None:
            self.times = self.times[self.times<=last]
        return self.times

    def extract_values(self, hdf_data, s, band_id): #Join bands with GITCO
        data_dict = {}
        mid = f"VIIRS-I{band_id}-SDR_All" if band_id else "VIIRS-IMG-GEO-TC_All"
        hdf_file = hdf_data[f"All_Data/{mid}/{s.split('_')[0]}"]
        data = hdf_file[:].astype(np.float32)
        data[data <= -999] = np.nan
        data[data >= 65527] = np.nan

        scale = 1 if not band_id else hdf_data[f"All_Data/{mid}/{s.split('_')[0]}Factors"][0].astype(np.float32)
        offset = 0 if not band_id else hdf_data[f"All_Data/{mid}/{s.split('_')[0]}Factors"][1].astype(np.float32)

        data = data*scale + offset
        data_dict[s] = data

        return data_dict
    
    def open_h5py(self, files:list) -> dict:
        geo_bands = ['SolarZenithAngle', 'SatelliteZenithAngle', 'Latitude', 'Longitude']
        img_bands = {'SVI01':'Reflectance_I1', 'SVI02':'Reflectance_I2', 'SVI04':'Radiance_I4', 'SVI05':'Radiance_I5'}
        temp_dict ={}

        for f_name in files:
            date_aq, time_aq = (f_name.name).split('_')[2:4]

            fs = gcsfs.GCSFileSystem()
            with fs.open(f'gs://{self.bucket}/{f_name.name}', mode='rb') as spec:
                with h5py.File(spec, 'r') as f:
                    if 'GITCO' in f_name.name:    
                        for s in geo_bands:
                            geo_dict = self.extract_values(f, s, None)
                            temp_dict.update(geo_dict)

                    elif 'SVI' in f_name.name:
                        s = img_bands[f_name.name.split('/')[-1].split('_')[0]]
                        id = s.split('_')[1][-1]
                        band_dict = self.extract_values(f, s, int(id))
                        temp_dict.update(band_dict)

        return temp_dict
    
    def group_files(self, files:list):
        return pd.DataFrame(
            {'files':files,
             'ids':['.'.join(f.name.split('_')[2:4]) for f in files]}
        ).groupby('ids').agg(lambda x: list(x)).files.values.tolist()
    
    
    def resample(self, data: dict, epsg=4326, max_distance_meter=1000, num_workers=8):
        swath_def = SwathDefinition(lons=data['Longitude'], lats=data['Latitude'])
        crs = CRS(f'EPSG:{epsg}')
        area_def = create_area_def(crs.name, crs.to_dict(), area_extent=self.region.bbox, resolution=self.region.pixel_size)
        valid_input_index, valid_output_index, index_array, distance_array = \
            kd_tree.get_neighbour_info(swath_def, area_def, max_distance_meter, neighbours=1, nprocs=num_workers)
        for k in self.bands:
            data[k] = kd_tree.get_sample_from_neighbour_info('nn', output_shape=self.region.shape, data=data[k], 
                                                   valid_input_index=valid_input_index, valid_output_index=valid_output_index,
                                                   index_array=index_array, distance_array=distance_array, fill_value=None)
        return data
    
    def process_one(self, time:pd.Timestamp, proc_funcs:list=[], save=True, replace=False, 
                    **proc_funcs_kwargs):
        """This method defines a processing pipeline consisting of opening the file
        using the `open` method, applying each of the `proc_funcs` to the output of the previous
        and `save` the processed data using save method."""
        tstr = time.strftime('%Y%m%d')
        files = self.list_files(time)
        files = self.group_files(files)
        tstr = time.strftime('%Y%m%d') #TODO daqui em diante
        filename = f'{self.paths.dst}/{self.name}{self.region.name}_{tstr}.nc'
        if not Path(filename).is_file() or replace:
            data_dict = {v:[] for v in self.bands}
            for file_group in files:
                data = self.open_h5py(file_group)
                data = self.resample(data)
                for v in self.bands:
                    data_dict[v].append(data[v])
            kwargs = {'cls': self, **proc_funcs_kwargs}
            for f in proc_funcs:
                data_dict = f(data_dict, time, **kwargs)
            if save:
                self.save(time, data_dict)
            else: return data_dict
        else: warn(f'Skipping files for {time}. File already exists.')



